python3 -c "
import json
with open('/app/resources/treasury_bulletin_1991_09.json', 'r') as f:
    data = json.load(f)

# Search for saving rate data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'saving' in k.lower() or 'after-tax' in k.lower() or 'percent' in k.lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
"

